function latestAmounts(orders){
  // orders: [{customerId, day, amount}]
  const out = {};
  for (const o of orders){
    if (!(o.customerId in out) || o.amount > out[o.customerId].amount){
      out[o.customerId] = { day: o.day, amount: o.amount };
    }
  }
  const result = {};
  for (const k in out) result[k] = out[k].amount;
  return result;
}

